"""Source-qualified private R3 checks. No Gradle, client or GPU launch."""
import copy,json,os,re,shutil,subprocess,sys,unittest,zipfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'scripts'))
import build_photon_live_pixel_remap as probe
M=json.loads((ROOT/probe.MANIFEST).read_text())
OUT=ROOT/'build/live-pixel-remap-r3-source-checks'

def select_remap(source):
    source=re.sub(r'// ShaderLOD R3 cloud remap and independent native TAA preservation; default off.\n(?://)?#define SHADERLOD_CLOUD_HISTORY_REMAP\n(?://)?#define SHADERLOD_TAA_SCALE_PRESERVE\n','',source)
    stack=[];out=[]
    for line in source.splitlines(keepends=True):
        if line in ('#ifdef SHADERLOD_CLOUD_HISTORY_REMAP\n','#if defined SHADERLOD_CLOUD_HISTORY_REMAP && defined SHADERLOD_LIVE_PIXEL_HISTORY_INCLUDED\n'):stack.append(False)
        elif line=='#else // SHADERLOD_REMAP_STAGE\n':stack[-1]=not stack[-1]
        elif line in ('#endif // SHADERLOD_REMAP_STAGE\n','#endif // SHADERLOD_CLOUD_HISTORY_REMAP\n'):stack.pop()
        elif not stack or all(stack):out.append(line)
    assert not stack
    return ''.join(out)
def expand(files,name):
    return re.sub(r'^\s*#include\s+"([^"]+)"[^\n]*',
        lambda m:expand(files,'shaders'+m[1] if m[1].startswith('/') else str(Path(name).parent/m[1])),
        files[name].decode(),flags=re.M)


def configured(files, private=True, taa=True, taau=True, voxy=False):
    files=files.copy(); s=files[probe.SETTINGS].decode()
    for name,value in [('TAA',taa),('TAAU',taau),('SHADERLOD_LIVE_PIXEL_HISTORY',private)]:
        s,n=re.subn(r'^[ \t]*(?://)?#define '+name+r'[ \t]*$',('#define ' if value else '//#define ')+name,s,flags=re.M)
        assert n==1,(name,n)
    for option in ('COLORED_LIGHTS','SH_SKYLIGHT','ENVIRONMENT_REFLECTIONS','SKY_REFLECTIONS'):
        s=re.sub(r'^\s*#define '+option+r'\s*$','//#define '+option,s,flags=re.M)
    files[probe.SETTINGS]=s.encode()
    return files

